def descriptor(root):
    value = tomllib.loads((Path(root) / DESCRIPTOR).read_text())
    if not test_contract.exact(value, DECLARED):
        raise ValueError('the endpoint claims change an exact retained native/function/type/evidence/TEST boundary')
    for row in value['reference']:
        old, new = json.loads(row['original_claim_json']), json.loads(row['proposed_claim_json'])
        expected = deepcopy(old)
        expected['evidence'].append(item(row))
        before = json.loads(row['original_native_json'])
        after = deepcopy(before)
        links = [link for link in after['link'] if (link['type'], link['to']) == ('reader', 'malachite-ferret/fn')]
        if len(links) != 1:
            raise ValueError('the endpoint claims lose a unique retained reader relation')
        links[0].setdefault('evidence', []).append(item(row))
        if (digest(old) != row['original_claim_sha256'] or digest(new) != row['proposed_claim_sha256']
                or digest(before) != row['original_native_sha256'] or digest(after) != row['proposed_native_sha256']
                or not test_contract.exact(new, expected) or not test_contract.exact(after, json.loads(row['proposed_native_json']))):
            raise ValueError('the endpoint claims change more than two exact owning appends')
    return value

def item(row):
    return json.loads(row['evidence_json'])

def native_type(row, field):
    return None if row['declared_'+field] == 'unset' else row['declared_'+field]

def symbol_key(row):
    return SymbolKey('7mfk', 'tbl', row['address'])

def original(row, link):
    return test_contract.exact(canonical(link), json.loads(row['original_claim_json']))

def qualified(row, link):
    return test_contract.exact(canonical(link), json.loads(row['proposed_claim_json']))

def registered(evidence):
    return evidence.get('mode') == MODE or evidence.get('path') == DESCRIPTOR or isinstance(evidence.get('key'), str) and evidence['key'].startswith(PREFIX)

def publication(link, evidence):
    return (registered(evidence) and sum(test_contract.exact(evidence, current) for current in link.evidence) == 1
            and any(link.owner.key == row[2] and evidence.get('key') == PREFIX+row[0]
                    and digest(canonical(link)) == row[11] for row in IDENTITIES))

def operation(row):
    return dict(cmd='link', meaning=row['owner'], type='reader', to='malachite-ferret/fn', evidence=[item(row)])

def operations(ops, root):
    selected = [op for op in ops if any(registered(evidence) for evidence in op.get('evidence', ()))]
    if not selected:
        return False
    if not test_contract.exact(selected, [operation(row) for row in descriptor(root)['reference']]):
        raise ValueError('the endpoint attachment requires both exact complete owning operations in their declared order')
    return True

def looks_like_access(link):
    return any(registered(evidence) for evidence in link.evidence) or any(
        (link.owner.key, link.type, link.to.key) == (row[2], 'reader', 'malachite-ferret/fn') for row in IDENTITIES)
